import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[][] data = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                data[i][j] = sc.nextLong();
            }
        }
        final long MOD = 1000000007L;
        long total_result = 0;
        int maxMask = 1 << n;
        for (int mask = 0; mask < maxMask; mask++) {
            long current_product = 1;
            for (int col_idx = 0; col_idx < n; col_idx++) {
                long val = 1;
                for (int row_idx = 0; row_idx < n; row_idx++) {
                    if ((mask & (1 << row_idx)) != 0) {
                        val = (val * data[row_idx][col_idx]) % MOD;
                    } else {
                        val = (val * ((MOD + 1 - data[row_idx][col_idx]) % MOD)) % MOD;
                    }
                }
                current_product = (current_product * val) % MOD;
            }
            total_result = (total_result + current_product) % MOD;
        }
        System.out.println(total_result);
        sc.close();
    }
}
